import base64,html,json,pathlib
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from run import CONDITIONS,SCENARIOS
P=pathlib.Path(__file__).resolve().parent
S=json.loads((P/'summary.json').read_text());A=json.loads((P/'AUDIT.json').read_text());V=json.loads((P/'VALIDATION.json').read_text());C=json.loads((P/'CALIBRATION.json').read_text())
assert not A['errors'] and V['status']=='PASS'
G={(g['level'],g['condition'],g['scenario']):g for g in S['groups']}
N={'learned':'Learned','ungated':'Ungated trained','uniform4':'Uniform 4','uniform2':'Uniform 2','directional':'Median rule everywhere','directional_tail':'Median rule after layer 6'}
T={'clean':'Clean','lateral_050':'Lateral 50%','lateral_100':'Lateral 100%','central_050':'Central 50%','noise_only':'Noise only','noise_mixed':'Noise + true','wrong_lane':'Wrong source lane'}
L={-1:'Quiet (one example)',0:'Low noise',1:'Medium noise',2:'High noise'}
def heatmap(key,scenes,title,name,cmap='Blues'):
    fig,axs=plt.subplots(1,3,figsize=(15.5,5.5),sharey=True)
    for ax,l in zip(axs,range(3)):
        a=np.array([[100*G[l,c,t][key]['mean'] for t in scenes] for c in CONDITIONS]);im=ax.imshow(a,vmin=0,vmax=100,cmap=cmap,aspect='auto')
        for i in range(len(CONDITIONS)):
            for j in range(len(scenes)):
                white=(cmap=='Blues' and a[i,j]>60) or (cmap=='RdYlGn' and (a[i,j]<15 or a[i,j]>85))
                ax.text(j,i,f'{a[i,j]:.1f}',ha='center',va='center',fontsize=9,color='white' if white else '#17212b')
        ax.set_xticks(range(len(scenes)),[T[t].replace(' ','\n',1) for t in scenes],fontsize=9);ax.set_yticks(range(len(CONDITIONS)),[N[c] for c in CONDITIONS],fontsize=9);ax.set_title(L[l]);ax.tick_params(length=0)
    fig.suptitle(title,fontsize=16);fig.text(.5,.025,'Means over 20 paired network seeds per noise level; 24 probes and 128 true source pulses per mixed trial.',ha='center',fontsize=10)
    fig.tight_layout(rect=[0,.07,1,.94]);fig.savefig(P/name,dpi=180);plt.close(fig)
probe_scenes=[t for t in SCENARIOS if t!='clean'];true_scenes=[t for t in SCENARIOS if t!='noise_only']
heatmap('false_reach',probe_scenes,'Primary endpoint: probe identities reaching layer 130 (%)','probe_reach.png')
heatmap('true_recall',true_scenes,'Primary endpoint: true identities recovered purely and exactly once (%)','true_recall.png','RdYlGn')
heatmap('pure_false_probe_reach',probe_scenes,'Complementary view: probes producing a false-only output (%)','pure_false_reach.png')
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def img(name):return '<img alt="'+name+'" src="data:image/png;base64,'+base64.b64encode((P/name).read_bytes()).decode()+'">'
def percent(v):return '—' if v is None else f'{100*v:.2f}%'
def stat(g,k):return '—' if g[k] is None else percent(g[k]['mean'])
def interval(v):return '—' if v is None else f"{100*v['mean']:+.2f} [{100*v['CI95'][0]:+.2f}, {100*v['CI95'][1]:+.2f}]"
t='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>A22 — Directional selectivity</title><style>body{font:16px/1.55 system-ui,sans-serif;color:#182a3e;max-width:1250px;margin:40px auto;padding:0 24px}h1{font-size:36px;line-height:1.15}h2{margin-top:40px;border-top:1px solid #dbe3eb;padding-top:20px}h3{font-size:19px}small,.muted{color:#57697b}.note{background:#edf5fa;border-left:4px solid #267ba8;padding:16px 20px;margin:20px 0}table{border-collapse:collapse;width:100%;font-size:14px;margin:18px 0}th,td{padding:10px 12px;border-bottom:1px solid #dbe3eb;text-align:left;vertical-align:top}th{background:#edf3f7}.scroll{overflow:auto}img{width:100%;height:auto}code{background:#edf3f7;padding:2px 5px}details{margin:16px 0}summary{cursor:pointer;font-weight:600}</style><body><p class="muted">A22 · FROZEN-NETWORK SELECTIVITY EXPERIMENT</p><h1>What does the learned gain structure buy?</h1><p>Six frozen configurations, seven input scenarios, three noise levels with twenty paired seeds each, plus one quiet example. Physical equations and costs are unchanged.</p>'''
t+='<div class="note"><b>Two questions are evaluated jointly.</b> Does a probe reach the output, and are true source pulses still recovered in its presence? Rejecting probes by failing to relay the true source is not a selective advantage. The homogeneous median rule is supplemented by a rule applied only after the learned entrance, so an entrance-broadcast failure cannot be mistaken for evidence of sophisticated interior computation.</div>'
if (P/'FINDINGS.txt').exists():
    t+='<h2>Findings</h2>'+''.join('<p>'+html.escape(p)+'</p>' for p in (P/'FINDINGS.txt').read_text().strip().split('\n\n'))
t+='<h2>Fixed comparisons and controls</h2>'
t+=table(['Configuration','Frozen gains','Frozen b'],[['Learned','Normally trained gains','Normally trained b'],['Ungated trained','Gains trained without READY gating','Its own ungated-trained b'],['Uniform 4','4 on every port','Same b as learned'],['Uniform 2','2 on every port','Same b as learned'],['Median rule everywhere',f"Central {C['central_gain']:.8f}; lateral {C['lateral_gain']:.8f} everywhere",'Same b as learned'],['Median rule after layer 6','Learned entrance layers 1–6; same median rule in layers 7–130','Same b as learned']])
t+='<p>The median pair was fixed from the 60 noisy normal-training checkpoints before probe results were inspected. It is a specified simple control, not a proven optimal static alternative. All tests freeze both gains and b, relax q to 0.1 and start E at 100. The ungated comparator changes both learned gain and recovery profiles; the uniform and median controls match b exactly to isolate gain-structure differences.</p>'
t+='<p><b>Directionality was not learned from an isotropic initialization.</b> Nominal initial gains are (0.3,1.2,0.3): the central port already starts four times stronger. The experiment tests adaptation and calibration of a biased architecture, not discovery of direction without prior bias. The median-rule-after-layer 6 control also retains the learned entrance and all learned b values; success of that hybrid would not establish that the entire learning process is unnecessary.</p>'
t+='<h2>Primary outcomes</h2>'+img('probe_reach.png')+img('true_recall.png')
t+='<p><b>Probe reach</b> is the fraction of the 24 injected identities found in any layer 130 output. Mixed true/probe outputs count as contamination. <b>Strict true recall</b> requires one pure output for each expected true identity/lane pair, with no additional mixed or duplicate occurrence. Full true-word success additionally requires order on all 12 output lanes. Pure false outputs interspersed between correctly recovered true pulses are scored separately.</p>'
t+='<h2>Mixed outputs are not automatically missing true signals</h2><p>The primary endpoints deliberately use a strict purity criterion. To distinguish contamination from extra false emissions, the complementary view counts probes that produce an output with no true identity. An inclusive true-recall diagnostic accepts a mixed output carrying exactly one true identity if that true identity appears exactly once; merged multiple true identities and duplicates still fail. These diagnostics are computed from the same raw outputs and are not substitutes chosen after changing the simulations.</p>'+img('pure_false_reach.png')
t+='<h2>Paired comparisons with the learned network</h2><p>The predeclared exploratory rule requires a 95% paired interval strictly below zero for probe-reach difference and a lower endpoint above −0.1 percentage point for strict true-recall difference. The tolerance is a practical choice, not proof of exact equality. Quiet cases and noise-only trials do not receive a joint selectivity verdict. No multiple-comparison adjustment is applied.</p>'
joint=[p for p in S['paired'] if p['level']>=0 and p['scenario'] not in ['clean','noise_only']]
t+=table(['Comparator','Joint rule met','How to interpret'],[[N[c],f"{sum(p['selective_advantage_rule_met'] for p in joint if p['comparator']==c)} / 15 noisy scenario/level comparisons",'Exploratory count; inspect effect sizes and fidelity below.'] for c in CONDITIONS[1:]])
for scene in ['lateral_100','noise_mixed','central_050','wrong_lane','lateral_050']:
    rows=[]
    for p in S['paired']:
        if p['scenario']==scene and p['level']>=0:rows.append([L[p['level']],N[p['comparator']],interval(p['false_reach']),interval(p['true_recall']),interval(p['pure_false_probe_reach']),interval(p['inclusive_true_recall']),'Yes' if p['selective_advantage_rule_met'] else 'No'])
    t+='<details><summary>'+T[scene]+' — paired differences and 95% intervals</summary><p>All differences are learned minus comparator, in percentage points. Lower probe reach and higher true recall favor learned.</p>'+table(['Noise','Comparator','Probe reach Δ','Strict true recall Δ','False-only reach Δ','Inclusive true recall Δ','Joint rule'],rows)+'</details>'
t+='<h2>Detailed rates, fidelity and cost</h2><p>The cost is the integral of the original nine-term W, in model work units. A lower cost with poor true recall is not an efficiency advantage at equal service. Costs in contaminated trials include processing the probes and their downstream effects; they should not be substituted directly for the earlier clean-test percentages.</p>'
for l in [-1,0,1,2]:
    rows=[]
    for scene in SCENARIOS:
        for c in CONDITIONS:
            g=G[l,c,scene];rows.append([T[scene],N[c],stat(g,'false_reach'),stat(g,'pure_false_probe_reach'),f"{g['pure_false_events']['mean']:.2f}",f"{g['mixed_events']['mean']:.2f}",stat(g,'true_recall'),stat(g,'inclusive_true_recall'),stat(g,'true_loss_vs_clean'),'—' if g['full_true_words'] is None else f"{g['full_true_words']}/{g['n']}",f"{g['work']['mean']/1e6:.4f}"])
    t+='<details><summary>'+L[l]+' — all configurations and scenarios</summary>'+table(['Scenario','Configuration','Probe reach','False-only reach','False-only output events','Mixed output events','Strict true recall','Inclusive true recall','Strict recall loss vs clean','Complete true words','Work ×10⁶'],rows)+'</details>'
t+='<h2>Injection protocol and its scope</h2><p>The true source is on lane0 and must reach all 12 final lanes. Twenty-four probes are inserted in source gaps3,8,…,118. Lateral and weakened central probes enter a single port at layer 7, visiting each lane twice; lateral tests visit both sides. Their times are the source-gap midpoint plus3, with the declared link jitter. Their base amplitudes are50% or100%, multiplied by the same paired lognormal link field.</p><p>Noise is a sparse pulse process: uniformly selected layer 7 lane and port, base amplitude uniform[0.3,1], and a bounded random timing offset. Exactly the same pulse realization is used with and without the true source. This does not test every noise process. Wrong-lane probes instead enter external source lane6; they test learned entrance geometry, not an interior route that was never active.</p>'
t+='<p>The source geometry matters. A homogeneous rule with central gain above the isolated-pulse threshold and lateral gain below it may preserve a single lane but fail the required broadcast. The learned-entrance median-rule control tests whether a simple interior rule suffices once that entrance problem is handled.</p>'
t+='<h2>Validation, attribution and limitations</h2>'
t+=table(['Check','Result'],[['Completed datasets',str(A['datasets'])],['Independent raw-output recounts',str(A['raw_output_recounts'])],['Unattributed final output events',str(A['unattributed_events'])],['Checked interstitial injection brackets',str(A['injection_brackets_checked'])],['Injection timing violations',str(A['injection_bracket_violations'])],['Audit errors',str(len(A['errors']))],['Minimum continuous reserve lower bound',f"{A['minimum_E_bound']:.6f}"],['Minimum sampled reserve',f"{A['minimum_sampled_E']:.6f}"],['Maximum normalized energy-accounting residual',f"{A['max_energy_relative_residual']:.3g}"]])
t+='<p>The physical kernel is inherited from the independently checked energy campaign. The extension carries passive provenance sets; tags do not change the charge, gain or recovery equations. Local tests cover analytic isolated-pulse thresholds, mixed provenance, true recovery and duplicate contamination. Clean learned and uniform4 full-network events and work exactly match earlier outputs. Frozen parameters, auxiliary section masses, fast drain, pump balance and monotone downstream provenance counts are audited across the campaign.</p><p>Provenance is the union of identities on currently active raw inputs at firing. It preserves mixed labels but is not a full counterfactual attribution of subthreshold charge memory. Strict purity loss should therefore be read alongside inclusive true delivery, false-only output rates, mixed-event counts and interval distortion. Per-layer profiles retain aggregate probe-reach rates, rather than per-identity disappearance histories.</p><p>These are numerical point simulations, not an interval proof. The nonoverlapping-auxiliary domain is enforced: solver failures are not dropped or counted as successful filtering. E remains positively bounded; no depleted-reserve behavior is claimed. Bootstrap intervals resample network seeds, not individual lanes or probes. Zero observed events does not establish zero risk in other realizations.</p>'
t+='<h2>Reproducibility</h2><p>See README.txt, PROTOCOL.json, CALIBRATION.json, metrics.csv, summary.json and the raw results. The archive includes all frozen input checkpoints, C++ sources, validation, reports, plots and checksums. Original model: <a href="https://github.com/HevisNico/a22-interval-replay">HevisNico/a22-interval-replay</a>, pinned commit 22294781127aa47628bb8a3270d5c5a758c31729. Source attribution and licenses are retained in reference/.</p></body></html>'
(P/'report.html').write_text(t);print('English report and three figures written.')
